// src/App.jsx
import React from 'react';
import { BrowserRouter as Router, Routes, Route } from 'react-router-dom';
import { AuthProvider } from './context/AuthContext';
import GlobalSidebar from './components/common/GlobalSidebar';
import ResultsAnalysis from './components/professor/ResultsAnalysis';
// Importez ici vos autres composants...

// Composant de mise en page avec la barre latérale
const LayoutWithSidebar = ({ children, userRole = 'professor' }) => {
  return (
    <div className="app">
      <GlobalSidebar userRole={userRole} />
      {children}
    </div>
  );
};

// Composant principal de l'application
const App = () => {
  return (
    <AuthProvider>
      <Router>
        <Routes>
          {/* Routes pour les professeurs */}
          <Route path="/professor/results-analysis/:quizId" element={
            <LayoutWithSidebar userRole="professor">
              <ResultsAnalysis />
            </LayoutWithSidebar>
          } />
          
          {/* Ajoutez ici vos autres routes... */}
          
          {/* Route par défaut */}
          <Route path="*" element={<div>Page non trouvée</div>} />
        </Routes>
      </Router>
    </AuthProvider>
  );
};

export default App;
